import os, csv, json, numpy as np

OUTDIR = "storage/noesis/nmap"

def sniff_rows(path):
    with open(path, 'r', encoding='utf-8-sig', newline='') as f:
        sample = f.read(2048); f.seek(0)
        try:
            dialect = csv.Sniffer().sniff(sample, delimiters=[',',';','\t',' '])
        except Exception:
            class _D: delimiter=','
            dialect = _D()
        rdr = csv.reader(f, dialect)
        return [row for row in rdr]

def read_pairs(path):
    S = set()
    if not os.path.exists(path): return S
    try:
        rows = sniff_rows(path)
    except Exception:
        return S
    if not rows: return S
    # header?
    start = 1
    try:
        int(rows[0][0]); int(rows[0][1])
        start = 0
    except Exception:
        start = 1
    for row in rows[start:]:
        if len(row) < 2: continue
        a = row[0].strip().strip('"').strip("'")
        b = row[1].strip().strip('"').strip("'")
        try:
            i = int(a); j = int(b)
        except Exception:
            continue
        if i == j: continue
        u, v = (i,j) if i < j else (j,i)
        S.add((u,v))
    return S

def norm_label(s):
    t = s.strip().lower().replace(' ','').replace('-','').replace('_','')
    m = {'xl':'xmin','xr':'xmax','yb':'ymin','yt':'ymax'}
    if t in m: return m[t]
    m2 = {'xmin':'xmin','xminimum':'xmin','xleft':'xmin','left':'xmin',
          'xmax':'xmax','xmaximum':'xmax','xright':'xmax','right':'xmax',
          'ymin':'ymin','ybottom':'ymin','bottom':'ymin',
          'ymax':'ymax','ytop':'ymax','top':'ymax'}
    return m2.get(t, t)

def read_boundary(path):
    S = set()
    if not os.path.exists(path): return S
    try:
        rows = sniff_rows(path)
    except Exception:
        return S
    if not rows: return S
    hdr = [c.strip().lower() for c in rows[0]]
    di = None; li = None
    for i,h in enumerate(hdr):
        if h in ('disc','id','index','i'): di = i
        if h in ('label','boundary','side','axis','edge','kind'): li = i
    start = 1 if di is not None and li is not None else 0
    if start == 0:
        di, li = 0, 1
    for row in rows[start:]:
        if len(row) <= max(di, li): continue
        ds = row[di].strip().strip('"').strip("'")
        ls = norm_label(row[li])
        try:
            d = int(ds)
        except Exception:
            continue
        if ls in {'xmin','xmax','ymin','ymax'}:
            S.add((d, ls))
    return S

def load_noesis():
    B = read_boundary("storage/noesis/exports/sota_243/active_boundary_tol1e8.csv")
    P = read_pairs   ("storage/noesis/exports/sota_243/active_pairs_tol1e8.csv")
    return {"name":"Noesis_243","B":B,"P":P}

def load_prometheus():
    # tolerate tol1e08 variant
    B = read_boundary("storage/Prometheus/nmap/n26/active_boundary_tol1e8.csv")
    if not B:
        B = read_boundary("storage/Prometheus/nmap/n26/active_boundary_tol1e08.csv")
    P = read_pairs("storage/Prometheus/nmap/n26/active_pairs_tol1e8.csv")
    if not P:
        P = read_pairs("storage/Prometheus/nmap/n26/active_pairs_tol1e08.csv")
    return {"name":"Prometheus_298","B":B,"P":P}

def load_inquire():
    # prefer explicitly named SOTA files
    B = read_boundary("storage/Inquire/nmap/n26/Inquire_207_SOTA_active_boundary_tol1e8.csv")
    if not B:
        B = read_boundary("storage/Inquire/nmap/n26/active_boundary_tol1e8.csv")
    P = read_pairs("storage/Inquire/nmap/n26/Inquire_207_SOTA_active_pairs_tol1e8.csv")
    if not P:
        P = read_pairs("storage/Inquire/nmap/n26/active_pairs_tol1e8.csv")
    return {"name":"Inquire_207","B":B,"P":P}

